#!/bin/bash
# Display simple information about computer's RAM and CPU usage

echo "CPU Usage:
$(grep 'cpu ' /proc/stat | awk '{usage=($2+$4)*100/($2+$4+$6)}')"
echo "RAM Usage:
$(free -h | grep Mem | awk '{print $3/ $2 " of " $2}')"
echo "Total RAM: $(free -h | grep Mem | awk '{print $2}')"
echo "CPU Model: $(grep model name /proc/cpuinfo | head -1 | awk '{print $3,$4}')"
